      "right": "jit_3p75.png",
      "gt": "right",
      "scored": false,
      "note": "warm-up, extreme difference, not scored"
    },
    {
      "id": "b2j1",
      "kind": "pair",
      "dimension": "roughness",
      "prompt": "which linework feels rougher?",
      "left": "jit_0p00.png",
      "right": "jit_1p25.png",
      "gt": "right"
    }
  ],
  "catches": [
    {
      "id": "b2c1",
      "image": "grain_8.png",
      "position": 5,
      "prompt": "which image feels more textured / grainy?",
      "dimension": "texture"
    }
  ],
  "pass_criteria": {
    "jitter": ">=4/5 judges correct on b2j1 and b2j3, and b2j2 (polarity) within each other's confidence bands. failing this invalidates the session substrate",
    "taper": {
      "roughness_polarity": ">=4/5 judges select fid2_taper15 (uniform) as rougher on b2t1 -> polarity confirmed (heavy taper = smoother)",
      "line_character": ">=4/5 judges select the heavy-taper side on b2t2 and b2t3 -> taper discriminable under calligraphic framing",
      "cross_cue": ">=4/5 judges select b2_jit2 (jitter) as rougher on b2t4 -> jitter roughness dominates when cues conflict",
      "verdict_rule": "line_character pass + roughness polarity pass -> promote taper to its own line_character axis with smoother polarity on roughness; line_character pass + roughness split (2/3) -> standalone axis, remove from roughness composite; both fail -> kill the taper candidate"
    },
    "grain": {
      "anchor_pass": "5/5 judges correct on b2g6 (0v14, extreme delta)",
      "jnd_floor": "lowest 0-v-X pair with >=4/5 agreement gives the floor bracket; if 0v8 fails while 0v11 passes, floor is between 8 and 11",
      "local_jnd": "8v11 and 11v14 agreement gives the JND in the working range",
      "d_prime": "b2g7 must yield >=4/5 'different' -> pilot miss was a which-is-more artifact, not a perceptual floor"
    },
    "lighting": ">=4/5 correct on b2l1 and b2l2 (corrected prompt validated); b2l4 agreement estimates the brightness JND near the top of the range",
    "general": "any scored pair with a 50/50 judge split is a stimulus failure, not human noise: regenerate at higher parameter delta in the next batch"
  },
  "adaptive_rules": {
    "catch_fail": "a judge answering >1 catch pair with a side choice instead of 'no difference' is excluded from aggregates; recruit a replacement to hold n=5",
    "grain_fail": "if 8v11 fails but 8v14 passes, the psychometric floor is between 11 and 14: next batch probes 11v13 and 12v14",
    "lighting_fail": "if 0.5v0.75 passes but 0.25v0.75 fails, lighting JND is above 0.25: next batch probes 0.5v1.0 (capped at substrate max)",
    "stimulus_fail": "50/50 splits get regenerated at higher contrast next batch and logged as stimulus-quality data",
    "convergence": "two consecutive batches with agreement values inside each other's bootstrap CIs at target n ends the loop for that dimension; the plateau is the metric's honest ceiling"
  },
  "registry_consequences": {
    "taper_promote": "taper -> validated under line_character, controllable_track",
    "taper_split": "taper -> measurable only, removed from roughness composite",
    "taper_kill": "taper -> demoted with evidence",
    "lighting_pass": "lighting_strength -> validated (brightness axis)",
    "lighting_fail": "lighting_strength -> stays measurable, prompt/JND work queued",
    "grain_pass": "texture_energy -> validated with floor bracket recorded"
  }
}
